document.addEventListener('click',async event=>{const button=event.target.closest('[id="#clearClaimHistory"],#clearClaimHistory');if(!button)return;if(!confirm('Clear saved policy and claim history?'))return;try{renderPolicyHistory(await api('/api/policies/clear',{}));}catch(error){const history=document.querySelector('#policyHistory');if(history)history.textContent=error.message;}});
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const demoAccounts={patient:{id:'carecost-patient',password:'PatientCare!2026'},agent:{id:'carecost-agent',password:'AgentCare!2026'}};
let selectedRole='patient';
function ensureSignOut(){
  const profile=document.querySelector('.profile');
  if(!profile)return;
  if(profile.firstChild?.nodeType===Node.TEXT_NODE)profile.firstChild.nodeValue='Patient workspace ';
  const avatar=profile.querySelector('span'); if(avatar)avatar.textContent='PT';
  if(!profile.querySelector('#signOut')){const button=document.createElement('button');button.id='signOut';button.className='sign-out';button.type='button';button.textContent='Sign out';profile.append(button);}
  if(profile.dataset.profileBound)return; profile.dataset.profileBound='1'; profile.classList.add('profile-trigger');
  profile.addEventListener('click',async event=>{
    if(event.target.closest('#signOut')||event.target.closest('#profilePopover'))return;
    let panel=document.querySelector('#profilePopover'); if(panel){panel.remove();return;}
    panel=document.createElement('section');panel.id='profilePopover';panel.className='profile-popover';panel.innerHTML='<div class="profile-popover-loading">Loading profile…</div>';profile.append(panel);
    const result=await fetch('/api/patient-profile?sign_id='+encodeURIComponent(sessionStorage.getItem('carepath-session')||'')).then(r=>r.json()).catch(()=>({})); const d=result.data||{},p=d.patient||{},policy=(d.policies||[])[0]||{};
    panel.innerHTML='<div class="popover-head"><b>Patient profile</b><button type="button" class="popover-close">×</button></div><div class="popover-name">'+esc(p.name||'Unknown patient')+'</div><div class="popover-grid"><span>Name<strong>'+esc(p.name||'Not stated')+'</strong></span><span>Age<strong>'+esc(p.age==null?'Not stated':p.age+' years')+'</strong></span><span>Gender<strong>'+esc(p.gender||'Not stated')+'</strong></span><span>Policy name<strong>'+esc(policy.name||'Not stated')+'</strong></span><span>Policy schema<strong>'+esc(policy.schema||'Not provided')+'</strong></span><span>Duration<strong>Not provided in dataset</strong></span></div><button type="button" id="addProfileButton" class="profile-add">＋ Add patient profile</button><div id="newProfileForm" class="new-profile-form" hidden><label>Full name<input id="newProfileName"></label><label>Phone<input id="newProfilePhone"></label><div class="form-grid"><label>Age<input id="newProfileAge" type="number"></label><label>Gender<select id="newProfileGender"><option>F</option><option>M</option><option>Other</option></select></label></div><label>Policy schema<select id="newProfileSchema"></select></label><label>Claim amount<input id="newProfileClaim" type="number"></label><label>Policy duration<input id="newProfileDuration"></label><div class="form-grid"><label>New Sign ID<input id="newProfileId"></label><label>Password<input id="newProfilePassword" type="password"></label></div><button type="button" id="saveProfileButton" class="primary">Save profile</button><p id="newProfileStatus" class="field-note"></p></div>';
    panel.querySelector('.popover-close').onclick=()=>panel.remove();
    const ageInput=panel.querySelector('#newProfileAge'); if(ageInput){ageInput.min='1';ageInput.max='150';ageInput.step='1';ageInput.required=true;}
    const loadPolicySchemas=async()=>{const select=panel.querySelector('#newProfileSchema');select.innerHTML='<option value="">Loading policy schemas…</option>';try{const response=await fetch('/api/policy-schemas');const result=await response.json();const schemas=Array.isArray(result.data)?result.data:[];if(!schemas.length){select.innerHTML='<option value="">No policy schemas available</option>';return;}select.innerHTML=schemas.slice(0,100).map(s=>'<option value="'+esc(s.schema)+'">'+esc(s.company)+' · '+esc(s.schema)+' · max '+fmt(s.max_claimable)+'</option>').join('');}catch(error){select.innerHTML='<option value="">Unable to load policy schemas</option>';}};
    panel.querySelector('#addProfileButton').onclick=async()=>{panel.querySelector('#newProfileForm').hidden=false;await loadPolicySchemas();};
    loadPolicySchemas();
    panel.querySelector('#saveProfileButton').onclick=async()=>{const payload={name:$('#newProfileName').value,phone:$('#newProfilePhone').value,age:$('#newProfileAge').value,gender:$('#newProfileGender').value,policy_schema:$('#newProfileSchema').value,claim_amount:$('#newProfileClaim').value,duration:$('#newProfileDuration').value,sign_id:$('#newProfileId').value,password:$('#newProfilePassword').value};try{const saved=await api('/api/patient-profiles',payload);$('#newProfileStatus').textContent='Saved '+saved.profile.name+'. Sign out to use the new credentials.';}catch(error){$('#newProfileStatus').textContent=error.message;}};
  });
}function mountProfilePage(){
  document.body.classList.add('profile-locked');
  const screen=document.createElement('section'); screen.id='profileScreen'; screen.className='profile-screen'; screen.innerHTML='<div class="profile-loading">Loading patient profile from the source datasets…</div>'; document.body.prepend(screen);
  fetch('/api/patient-profile?sign_id='+encodeURIComponent(sessionStorage.getItem('carepath-session')||'')).then(response=>response.json()).then(result=>{const data=result.data||{};const patient=data.patient||{};const policy=(data.policies||[])[0]||{};const care=data.care_summary||{};screen.innerHTML=`<div class="profile-page-top"><div class="login-brand"><span>✦</span> CarePath <small>COST &amp; CLAIM INTELLIGENCE</small></div><span class="profile-step">02 / 03 · PATIENT PROFILE</span></div><div class="profile-page-body"><div class="profile-intro"><p class="eyebrow">SOURCE-BACKED PATIENT PROFILE</p><h1>Know the person<br><em>behind the policy.</em></h1><p>These details are read from the project’s existing healthcare CSV datasets. Missing fields are shown clearly rather than inferred.</p><span class="profile-source">⌁ ${data.source||'Existing healthcare CSV datasets'}</span></div><section class="patient-card"><div class="patient-card-head"><span class="patient-avatar">${(patient.name||'Patient').split(' ').filter(Boolean).slice(0,2).map(part=>part[0]).join('').toUpperCase()}</span><div><small>PATIENT RECORD</small><h2>${esc(patient.name||'Unknown patient')}</h2><span>Record ID · ${esc(patient.id||'Not stated')}</span></div><span class="record-badge">CSV record</span></div><div class="patient-fields"><div><small>PHONE NUMBER</small><strong>${esc(patient.phone||'Not provided')}</strong></div><div><small>AGE</small><strong>${patient.age==null?'Not stated':patient.age+' years'}</strong></div><div><small>GENDER</small><strong>${esc(patient.gender||'Not stated')}</strong></div><div><small>BIRTH DATE</small><strong>${esc(patient.birthdate||'Not stated')}</strong></div><div><small>LOCATION</small><strong>${esc(patient.location||'Not stated')}</strong></div></div><div class="policy-section"><div><small>POLICY / PAYER</small><h3>${esc(policy.name||'Not stated')}</h3><span>Member / payer ID · ${esc(policy.member_id||'Not stated')}</span></div><div><small>PAYER PHONE</small><strong>${esc(policy.phone||'Not provided')}</strong><span>${esc(policy.status||'Source record')}</span></div></div><div class="care-summary"><div><small>RECORDED ENCOUNTERS</small><strong>${care.encounters||0}</strong></div><div><small>LATEST CARE TYPE</small><strong>${esc(care.latest_type||'Not stated')}</strong></div><div><small>LAST RECORDED FACILITY</small><strong>${esc(care.latest_facility||'Not stated')}</strong></div><div><small>LAST RECORDED DATE</small><strong>${esc(care.latest_date||'Not stated')}</strong></div></div></section><div class="profile-actions"><span>Review the profile, then continue to the full CarePath workspace.</span><button id="continueWorkspace" class="primary">Continue to workspace <b>→</b></button></div></div><div class="profile-page-footer"><span>CarePath · Patient workspace</span><span>Page 2 of 3 · Source values are illustrative dataset records</span></div>`;$('#continueWorkspace').onclick=()=>{sessionStorage.setItem('carepath-page','workspace');document.body.classList.remove('profile-locked');screen.remove();ensureSignOut();show('overview');};}).catch(()=>{screen.innerHTML='<div class="profile-loading">Unable to load the patient CSV profile. Please restart the local server and try again.</div>';});
}
function mountLogin(){
  document.body.classList.add('auth-locked');
  const screen=document.createElement('section'); screen.id='loginScreen'; screen.className='login-screen'; screen.innerHTML=`<div class="login-rail"><div class="login-brand"><span>✦</span> CarePath <small>COST &amp; CLAIM INTELLIGENCE</small></div><div class="login-rail-copy"><p class="eyebrow">FINANCIAL DECISION SUPPORT</p><h1>Plan care with<br><em>more clarity.</em></h1><p>Bring estimates, policy assumptions, hospital listings and bill review into one calm workspace.</p><div class="login-points"><span>✓ Dataset-backed planning estimates</span><span>✓ India hospital directory and tariffs</span><span>✓ Explainable claim safeguards</span></div></div><div class="login-rail-footer">CarePath · A clearer view of care costs</div></div><div class="login-panel"><div class="login-panel-top"><span>PRIVATE WORKSPACE</span><span class="secure-label"><i></i> Secure session</span></div><div class="login-box"><span class="login-kicker">WELCOME BACK · SIGN IN</span><h2>Sign in to CarePath</h2><p>Choose your workspace, then enter your credentials.</p><div class="login-roles"><button type="button" class="login-role active" data-role="patient">Patient</button><button type="button" class="login-role" data-role="agent">Insurance agent</button></div><form id="loginForm"><label>Sign ID<input id="loginId" autocomplete="username" placeholder="Enter your Sign ID" required></label><label>Password<div class="password-wrap"><input id="loginPassword" type="password" autocomplete="current-password" placeholder="Enter your password" required><button type="button" id="togglePassword">Show</button></div></label><p id="loginError" class="login-error" hidden></p><button class="login-submit" type="submit">Sign in <b>→</b></button></form><p class="login-note">◈ Local demo accounts are verified for this workspace only.</p><div class="demo-hint"><b>Demo access</b><span>Patient: carecost-patient · PatientCare!2026</span></div></div><div class="login-panel-footer"><span>CarePath AI</span><span>Private sign in · Secure session</span></div></div>`;
  document.body.prepend(screen);
  screen.querySelector('.login-role[data-role="patient"]').textContent='User';
  screen.querySelector('.demo-hint span').textContent='User: carecost-patient · PatientCare!2026';
  const unlock=()=>{document.body.classList.remove('auth-locked');screen.remove();document.querySelector('#workspaceLabel')?.replaceChildren(document.createTextNode('Patient workspace'));document.querySelector('#profileInitials')?.replaceChildren(document.createTextNode('PT'));sessionStorage.setItem('carepath-page','workspace');ensureSignOut();show('overview');};
  $$('.login-role').forEach(button=>button.onclick=()=>{$$('.login-role').forEach(item=>item.classList.remove('active'));button.classList.add('active');selectedRole=button.dataset.role;});
  $('#togglePassword').onclick=()=>{const input=$('#loginPassword');const visible=input.type==='text';input.type=visible?'password':'text';$('#togglePassword').textContent=visible?'Show':'Hide';};
  $('#loginForm').onsubmit=async event=>{event.preventDefault();const id=$('#loginId').value.trim();const password=$('#loginPassword').value;const error=$('#loginError');try{const response=await fetch('/api/auth/patient-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sign_id:id,password})});const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw new Error('Static deployment');const result=await response.json();if(!response.ok)throw new Error(result.error||'Invalid patient credentials.');sessionStorage.setItem('carepath-session',id);unlock();}catch(err){if(id===demoAccounts.patient.id&&password===demoAccounts.patient.password){sessionStorage.setItem('carepath-session',id);unlock();return;}error.textContent='Use the demo credentials shown below.';error.hidden=false;}};
}
if(sessionStorage.getItem('carepath-session')){document.querySelector('#workspaceLabel')?.replaceChildren(document.createTextNode('Patient workspace'));document.querySelector('#profileInitials')?.replaceChildren(document.createTextNode('PT'));ensureSignOut();document.body.classList.remove('profile-locked');}else mountLogin();
document.addEventListener('click',event=>{if(event.target.closest('#signOut')){sessionStorage.removeItem('carepath-session');location.reload();}});
const fmt=n=>'₹'+Number(n||0).toLocaleString('en-IN'); let billItems=[];
async function api(path,data){let r,j;try{r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});j=await r.json()}catch(e){throw Error('Cannot reach the local server. Restart it and try again.')}if(!r.ok||j.success===false)throw Error(j.error||j.data?.error||`Request failed (${r.status})`);return j.data}
function show(view){$$('.view').forEach(x=>x.classList.toggle('visible',x.id===view));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#title').textContent=({overview:'Plan care with clarity',estimate:'Cost estimator',insurance:'Insurance calculator',hospitals:'Hospital comparison',bill:'Bill & document intelligence',claims:'Claim safeguards',exposure:'90-day exposure'})[view]}
$$('.nav').forEach(x=>x.onclick=()=>{show(x.dataset.view);if(x.dataset.view==='claims')loadPolicyHistory()});$$('.go-estimate').forEach(x=>x.onclick=()=>show('estimate'));
let tariffProcedures=[];
function populateProcedureList(){let category=$('#procedureCategory').value;let values=category?tariffProcedures.filter(x=>x.speciality===category):tariffProcedures;$('#procedureList').innerHTML=values.map(x=>`<option value="${x.name.replaceAll('"','&quot;')}">`).join('');$('#procedureCount').textContent=`${values.length.toLocaleString('en-IN')} tariff procedures available${category?` in ${category}`:''}.`}
Promise.all([fetch('/api/procedures').then(r=>r.json()),fetch('/api/procedure-categories').then(r=>r.json())]).then(([procedures,categories])=>{tariffProcedures=procedures.data;$('#procedureCategory').innerHTML='<option value="">All specialties</option>'+categories.data.map(x=>`<option value="${x.replaceAll('"','&quot;')}">${x}</option>`).join('');populateProcedureList()}).catch(()=>{$('#procedureCount').textContent='Tariff procedure catalogue is temporarily unavailable.'});
$('#procedureCategory').onchange=populateProcedureList;
function esc(value){return String(value||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
async function loadHospitals(){try{let q=$('#hospitalSearch').value.trim(), state=$('#hospitalState').value;let url='/api/hospitals?'+new URLSearchParams({q,state});let d=(await (await fetch(url)).json()).data;if($('#hospitalState').options.length===1)$('#hospitalState').innerHTML='<option value="">All states</option>'+d.states.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('');$('#directoryNote').textContent=`Showing ${d.records.length} matching listings from ${d.total_directory_records.toLocaleString('en-IN')} records. ${d.tier_note}`;$('#directoryTable').innerHTML=d.records.length?d.records.map(h=>`<tr><td>${esc(h.name)}</td><td>${esc(h.district)}, ${esc(h.state)}</td><td><span class="badge consistent">${esc(h.tier)}</span></td><td>${esc(h.category)}</td><td>${esc(h.care_type)}</td><td class="specialty">${esc(h.specialties)}</td></tr>`).join(''):'<tr><td colspan="6">No matching hospital listings. Try a state, a hospital name, or a broader specialty.</td></tr>'}catch(e){$('#directoryNote').textContent='Hospital directory is unavailable. '+e.message}}
$('#findHospitals').onclick=loadHospitals;
function estimateHTML(d){return `<p class="result-title">ESTIMATED TREATMENT COST</p><div class="result-value">${fmt(d.midpoint)}</div><div class="range">${fmt(d.low)} – ${fmt(d.high)}</div><div class="line"></div><div class="break">${d.breakdown.map(x=>`<div><span>${x.name}</span><b>${fmt(x.value)}</b></div>`).join('')}</div><div class="line"></div><p class="result-title">REFERENCE TARIFF</p><b>${fmt(d.tariff)}</b><p class="caption">${d.source} · ${d.source_date} · ${d.tier}<br>${d.confidence}</p>`}
$('#estimateForm').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/estimate',{procedure:$('#procedure').value,city:$('#city').value,hospital_type:$('#hospitalType').value,room:$('#room').value,stay:$('#stay').value});$('#estimateResult').innerHTML=estimateHTML(d);$('#summaryCost').textContent=`${fmt(d.low)}–${fmt(d.high)}`;if($('#estimatePolicyBill'))$('#estimatePolicyBill').value=d.midpoint;if($('#estimateInvoice'))$('#estimateInvoice').value=`${d.procedure} estimate`;renderHospitals(d)}catch(e){$('#estimateResult').innerHTML=`<p class="muted">${e.message}</p>`}};
$('#estimate .two-col').insertAdjacentHTML('afterend',`<div class="estimate-policy"><div class="page-intro estimate-cover-intro"><p class="eyebrow">ESTIMATE INSURANCE COVERAGE</p><h2>See what your estimate may be covered by</h2><p>Separate from Claim Safeguards. Policy terms are demo-derived until insurer data is connected.</p></div><div class="two-col"><form class="card form" id="estimatePolicyForm"><div class="step">01 <span>Look up insurance policy</span></div><div class="form-grid"><label>Insurance company<input id="estimatePolicyCompany" placeholder="e.g. LIC"></label><label>Policy number<input id="estimatePolicyNumber" placeholder="Policy reference"></label></div><button class="secondary" type="submit">Extract policy coverage</button><div id="estimatePolicyTwo" hidden><div class="step">+ <span>Second policy</span></div><div class="form-grid"><label>Second company<input id="estimatePolicyCompany2"></label><label>Second policy number<input id="estimatePolicyNumber2"></label></div><button class="secondary" type="button" id="estimateLookupTwo">Extract second policy</button></div><div id="estimatePolicyThree" hidden><div class="step">+ <span>Third policy</span></div><div class="form-grid"><label>Third company<input id="estimatePolicyCompany3"></label><label>Third policy number<input id="estimatePolicyNumber3"></label></div><button class="secondary" type="button" id="estimateLookupThree">Extract third policy</button></div><button class="secondary" type="button" id="estimateAddPolicy">＋ Add another policy</button><div class="step">02 <span>Compare against estimate</span></div><div class="form-grid"><label>Estimate reference<input id="estimateInvoice" value="Treatment estimate"></label><label>Estimated treatment cost<input id="estimatePolicyBill" type="number" value="0"></label></div><button class="primary" type="button" id="estimateRecommend">Find best estimated cover <b>→</b></button></form><section class="card results" id="estimateCoverResult"><p class="result-title">ESTIMATED POLICY COVERAGE</p><p class="muted">Look up up to three policies, then compare them against the treatment estimate.</p></section></div><section class="card history estimate-policy-history"><div class="card-head"><h3>Estimate policy & claim history</h3><span>Separate local demo history</span></div><div id="estimatePolicyHistory" class="items"><p class="muted">No estimate-coverage policies saved yet.</p></div></section></div>`);
if($('#insuranceForm'))$('#insuranceForm').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/insurance/calculate',{total:$('#insuredTotal').value,sum_insured:$('#sumInsured').value,deductible:$('#deductible').value,copay:$('#copay').value,non_payable:$('#nonPayable').value,room_excess:$('#roomExcess').value});$('#insuranceResult').innerHTML=`<p class="result-title">ESTIMATED PATIENT SHARE</p><div class="result-value">${fmt(d.patient_share)}</div><span class="badge consistent">Deterministic calculation</span><div class="line"></div>${d.lines.map(x=>`<div class="calc-row"><span>${x.label}</span><b>${x.value<0?'−':''}${fmt(Math.abs(x.value))}</b></div>`).join('<div style="height:8px"></div>')}<p class="caption">Policy type: ${esc($('#policyType').value)}. Check exclusions, room-rent rules and pre-authorisation with the insurer.</p>`;$('#summaryInsurance').textContent=fmt(d.contribution);$('#summaryShare').textContent=fmt(d.patient_share)}catch(e){$('#insuranceResult').textContent=e.message}};
function renderHospitals(d){const plans=[['Tier I · Private room',d.midpoint,5500*+$('#stay').value,+$('#stay').value],['Tier II · Semi-private',Math.round(d.midpoint*.9),3000*+$('#stay').value,+$('#stay').value],['Tier III · General',Math.round(d.midpoint*.78),1600*+$('#stay').value,+$('#stay').value]];$('#hospitalTable').innerHTML=plans.map(p=>{let cover=Math.max(0,Math.min(500000,(p[1]-12000)*.9)), share=p[1]-cover;return `<tr><td>${p[0]}</td><td>${fmt(p[1])}</td><td>${fmt(p[2])}</td><td>${p[3]} days</td><td>${fmt(cover)}</td><td>${fmt(share)}</td></tr>`}).join('')}
function drawItems(){ $('#billItems').innerHTML=billItems.map((x,i)=>`<div class="item-row"><span>${x.name} <small>× ${x.quantity} at ${fmt(x.unit_price)}</small></span><b>${fmt(x.total)}</b><button class="remove" data-i="${i}">×</button></div>`).join('');$$('.remove').forEach(x=>x.onclick=()=>{billItems.splice(+x.dataset.i,1);drawItems()})}
$('#scanBill').onclick=async()=>{let file=$('#billFile').files[0];if(!file){$('#scanStatus').textContent='Choose a hospital bill file first.';return}if(file.size>12*1024*1024){$('#scanStatus').textContent='Choose a file smaller than 12 MB.';return}try{$('#scanStatus').textContent='Extracting bill details…';let buffer=await file.arrayBuffer(), bytes=new Uint8Array(buffer), binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));let d=await api('/api/bills/scan-upload',{filename:file.name,data:btoa(binary)});billItems=d.items;drawItems();$('#billProcedure').value=d.procedure||'';$('#billStay').value=d.stay||'';$('#scanText').textContent=d.extracted_text_preview||'No readable text extracted.';$('#scanPreview').open=true;$('#scanStatus').textContent=`${d.message} ${d.confidence}${d.procedure?'':' Procedure was not stated in this bill; enter it only if you can verify it.'}${d.stay?'':' Stay duration was not stated in this bill; enter it only if you can verify it.'}`}catch(e){$('#scanStatus').textContent='Could not extract this bill: '+e.message}};
$('#addItem').onclick=()=>{let q=+$('#itemQuantity').value,p=+$('#itemPrice').value,n=$('#itemName').value.trim();if(n&&q&&p){billItems.push({name:n,quantity:q,unit_price:p,total:q*p});drawItems()}};
$('#billForm').onsubmit=async e=>{e.preventDefault();try{let d=await api('/api/bills/analyze',{items:billItems,procedure:$('#billProcedure').value,stay:$('#billStay').value});$('#claimBill').value=d.total;$('#claimInvoice').value=$('#billFile').files[0]?.name||'Verified hospital invoice';let consistent=d.consistent_items.length?`<div class="line"></div><p class="result-title">CONSISTENT WITH STATED TREATMENT</p><p class="caption">${d.consistent_items.join(', ')}</p>`:'';$('#billResult').innerHTML=`<p class="result-title">BILL TOTAL</p><div class="result-value">${fmt(d.total)}</div><span class="badge ${d.risk==='LOW'?'consistent':d.risk==='HIGH'?'high':'medium'}">${d.risk} REVIEW PRIORITY</span><div class="line"></div>${d.flags.length?d.flags.map(x=>`<div class="flag"><b>${x.title}</b><p>${x.detail}</p></div>`).join(''):'<p class="muted">No unusual patterns found in the supplied items.</p>'}${consistent}<p class="caption">${d.message}</p><button class="primary" id="continueToClaims" type="button">Continue to insurance claims →</button>`;$('#continueToClaims').onclick=()=>{show('claims');loadPolicyHistory()}}catch(e){$('#billResult').textContent=e.message}};
function renderPolicyHistory(d){let policies=d.policies||[],claims=d.claims||[];$('#policyHistory').innerHTML=policies.length?policies.map(p=>{let past=claims.filter(c=>c.policy_number===p.policy_number);return `<div class="flag"><b>${esc(p.company)} · ${esc(p.policy_number)}</b><p>Available claim cover ${fmt(p.remaining_cover)} of ${fmt(p.sum_insured)} · ${p.supports_multiple_claims?'Multiple claims supported':'Single-claim profile'}</p><p>${esc(p.criteria||'No policy criteria supplied.')} <small>· ${esc(p.lookup_source||'Local record')}</small></p><p>${past.length?`${past.length} saved claim(s): ${past.map(c=>`${esc(c.invoice)} (${fmt(c.claimed_amount)})`).join(', ')}`:'No saved claims yet.'}</p></div>`}).join(''):'<p class="muted">No policy saved yet. This local demo stores up to three policies on this computer.</p>'}
function renderPolicyDetails(policies){let list=policies||[];$('#policyDetails').innerHTML=list.length?`<p class="result-title">EXTRACTED POLICY DETAILS</p>${list.map(p=>`<div class="policy-highlight"><div><small>INSURER</small><strong>${esc(p.company)}</strong></div><div><small>POLICY NUMBER</small><strong>${esc(p.policy_number)}</strong></div><div><small>AVAILABLE COVER</small><strong>${fmt(p.remaining_cover)}</strong></div><div><small>MULTIPLE CLAIMS</small><strong>${p.supports_multiple_claims?'Supported':'Not supported'}</strong></div></div><p class="caption">${esc(p.criteria||'No policy criteria supplied.')}<br>${esc(p.lookup_source||'Saved local policy record')}</p>`).join('<div class="line"></div>')}`:'<p class="result-title">EXTRACTED POLICY DETAILS</p><p class="muted">Look up a policy to view its highlighted terms.</p>'}
async function loadPolicyHistory(){try{let r=await fetch('/api/policies'),j=await r.json();renderPolicyHistory(j.data||{})}catch(e){$('#policyHistory').textContent='Policy history is unavailable.'}}
async function extractPolicy(companyId,numberId){let company=$(companyId).value,number=$(numberId).value;let policy=await api('/api/policies/lookup',{company,policy_number:number});let d=await api('/api/policies/save',policy);renderPolicyHistory(d);renderPolicyDetails([policy]);$('#policyLookupStatus').textContent=`${policy.lookup_source}: ${policy.company} provides ${fmt(policy.remaining_cover)} available cover and ${policy.supports_multiple_claims?'supports':'does not support'} multiple claims. ${policy.criteria||''}`;$('#claimResult').innerHTML='<p class="result-title">BEST CLAIM FOR THIS INVOICE</p><p class="muted">Policy saved. Add another policy or find the best cover for the invoice.</p>'}
