async function recommendClaims(save=false){try{let payload={invoice:$('#claimInvoice').value,bill_total:$('#claimBill').value};let d=await api(save?'/api/claims/save':'/api/claims/recommend',payload),best=d.allocations[0];$('#claimResult').innerHTML=`<p class="result-title">BEST CLAIM FOR THIS INVOICE</p>${best?`<span class="best-badge">BEST POLICY · MAXIMUM COVER</span><div class="result-value" style="font-size:27px">${fmt(best.amount)}</div><p><b>${esc(best.company)}</b> · ${esc(best.policy_number)}</p>`:`<p class="result-title">${d.status}</p><div class="result-value" style="font-size:27px">₹0</div>`}<p class="caption">Invoice ${fmt(d.bill_total)} · total planned cover ${fmt(d.bill_total-d.remaining)} · uncovered ${fmt(d.remaining)}</p><div class="line"></div>${d.allocations.length?d.allocations.map((x,i)=>`<div class="calc-row"><span>${i?'Additional policy':'Best policy'} · ${esc(x.company)} · ${esc(x.policy_number)}</span><b>${fmt(x.amount)}</b></div>`).join(''):'<p class="muted">No available policy cover was found.</p>'}${d.notes.map(x=>`<div class="flag"><b>Claim safeguard</b><p>${esc(x)}</p></div>`).join('')}${save?'<p class="caption">Claim history saved locally. Insurer approval is still required.</p>':'<button class="primary" id="saveClaims" type="button">Save recommended claims</button>'}`;if(!save&&$('#saveClaims'))$('#saveClaims').onclick=async()=>{await recommendClaims(true);loadPolicyHistory()}}catch(e){$('#claimResult').textContent=e.message}}
