$('#scanBill').onclick=async()=>{let file=$('#billFile').files[0];if(!file){$('#scanStatus').textContent='Choose a hospital bill file first.';return}if(file.size>12*1024*1024){$('#scanStatus').textContent='Choose a file smaller than 12 MB.';return}try{$('#scanStatus').textContent='Extracting bill details…';let buffer=await file.arrayBuffer(),bytes=new Uint8Array(buffer),binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));let d=await api('/api/bills/scan-upload',{filename:file.name,data:btoa(binary)});billItems=d.items;drawItems();$('#billProcedure').value=d.procedure||'';$('#billStay').value=d.stay||'';currentBillText=d.extracted_text_preview||'';$('#scanText').textContent=currentBillText||'No readable text extracted.';$('#scanPreview').open=true;let saved=await api('/api/bills/history/save',{filename:file.name,procedure:d.procedure,stay:d.stay,items:d.items,text_preview:currentBillText});currentBillHistoryId=saved.record.id;renderBillHistory(saved);$('#scanStatus').textContent=`${d.message} ${d.confidence} Saved to local bill history; verify all values before analysis.`}catch(e){$('#scanStatus').textContent='Could not extract this bill: '+e.message}};
